/*
 * utf8_boundary.h - where a stream of generated bytes may be cut without splitting a UTF-8 character.
 *
 * Internal to the littlemore library (not installed). Kept in its own header, in plain C, so that the library
 * (C++) and the unit test tests/c/test_utf8.c (C) use the very same function.
 *
 * Why: tokens of byte-level vocabularies can end in the middle of a multi-byte UTF-8 character (an emoji may be
 * spread over three tokens). The streaming code gives the callback everything up to the boundary this function
 * returns and holds back the rest until the next token arrives. No byte is ever changed or dropped: invalid
 * sequences (a lone continuation byte, a byte 0xF8..0xFF, a lead byte followed by ASCII) do not look like the
 * beginning of an unfinished character, so they are passed through as they are.
 */
#ifndef LITTLEMORE_UTF8_BOUNDARY_H
#define LITTLEMORE_UTF8_BOUNDARY_H

#include <stddef.h>

/*
 * Returns the length of the longest prefix of s[0..n) that does not end inside an UNFINISHED UTF-8 sequence:
 * n itself, unless the last 1-3 bytes are a lead byte (0xC0..0xF7) followed by fewer continuation bytes
 * (0x80..0xBF) than it announces; then the position of that lead byte.
 *
 * Only the last 3 bytes need looking at: a UTF-8 character is at most 4 bytes, so an unfinished one has its lead
 * byte within the last 3. If those 3 bytes are all continuation bytes, there is no unfinished character to wait
 * for (either a 4-byte character ends here or the bytes are invalid) and everything is passed on.
 */
static inline size_t lm_utf8_complete_prefix(const char * s, size_t n) {
    size_t back;
    for (back = 1; back <= 3 && back <= n; ++back) {
        const unsigned char c = (unsigned char) s[n - back];
        size_t need;
        if ((c & 0xC0) == 0x80) {
            continue; /* continuation byte: keep looking for the lead byte */
        }
        if ((c & 0xE0) == 0xC0) {
            need = 2;
        } else if ((c & 0xF0) == 0xE0) {
            need = 3;
        } else if ((c & 0xF8) == 0xF0) {
            need = 4;
        } else {
            need = 1; /* ASCII, or an invalid byte 0xF8..0xFF that no continuation can complete */
        }
        return back < need ? n - back : n;
    }
    return n;
}

#endif /* LITTLEMORE_UTF8_BOUNDARY_H */
